use leptos::prelude::*;

/// Which rendition of the logo to draw.
#[derive(Clone, Copy, PartialEq, Eq, Default)]
pub enum LogoVariant {
    /// Mark + wordmark — the sidebar brand.
    #[default]
    Full,
    /// The standalone mark — the onboarding hero.
    Mark,
}

/// The Staw logo, inlined so the wordmark follows the theme's text color
/// (`.cv-logo__word`), while the mark stays brand green (`.cv-logo__mark`). Size it
/// per call site through `class` — set a height, width follows the viewBox.
